const {chromium}=require('playwright');const fs=require('fs');
(async()=>{const b=await chromium.launch({executablePath:'/root/.cache/ms-playwright/chromium-1161/chrome-linux/chrome',headless:true,args:['--no-sandbox']});const p=await b.newPage({viewport:{width:1100,height:1000}});let errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://127.0.0.1:8765');await p.waitForFunction(()=>document.querySelector('video')?.readyState>=2);let rows=[];
for(const t of [49.8,49.981,50.115,50.315,50.381,50.5,50.381]){await p.evaluate(async t=>{const v=document.querySelector('video');v.pause();await new Promise(r=>{v.addEventListener('seeked',r,{once:true});v.currentTime=t});},t);await p.waitForTimeout(200);rows.push(await p.evaluate(()=>({time:document.querySelector('video').currentTime,lines:document.querySelectorAll('svg line').length,polygons:document.querySelectorAll('svg mask polygon').length,head:document.querySelector('svg marker')?.getAttribute('markerWidth')})));if(t===50.381)await p.screenshot({path:'browser_review/player.png'});}
await p.evaluate(()=>{const v=document.querySelector('video');v.currentTime=49.8;v.playbackRate=.5;});await p.waitForTimeout(200);await p.evaluate(()=>{window.drawn=[];const v=document.querySelector('video');function f(_,m){const line=document.querySelector('svg line');window.drawn.push({ms:m.mediaTime*1000,line:!!line});if(m.mediaTime<50.6)v.requestVideoFrameCallback(f);}v.requestVideoFrameCallback(f);v.play();});await p.waitForFunction(()=>document.querySelector('video').currentTime>50.6);await p.evaluate(()=>document.querySelector('video').pause());let playback=await p.evaluate(()=>window.drawn);fs.writeFileSync('browser_review/result.json',JSON.stringify({errors,rows,playback,sourceStatus:await p.evaluate(()=>window.sourceStatus)},null,2));console.log(JSON.stringify({errors,rows,frames:playback.length,withArrow:playback.filter(x=>x.line).length}));await b.close();})().catch(e=>{console.error(e);process.exit(1)});
